    ["dog wont stop barking at [the basement door|the back fence]. probably a raccoon"] = "собака не перестаёт лаять на [дверь подвала|задний забор]. наверное, енот",
    ["ambulance never came. driving her myself. [taking the back roads|dont call]"] = "скорая так и не приехала. везу её на машине. [еду просёлками|не звони]",
    ["chained the gate. keep the kids inside [no matter what|till i get back]"] = "ворота на цепи. дети пусть сидят дома [что бы ни случилось|пока я не вернусь]",
    ["The pastor came by and prayed with me. Said the church is full. I'm all right here"] = "Приходил пастор, помолился со мной. Сказал, что церковь переполнена. Мне здесь хорошо",
    ["nailed boards over the [bedroom|kitchen] window. [told the kids its a game|kids are asleep]"] = "заколочено досками окно [спальни|кухни]. [детям сказано, что это игра|дети спят]",
    ["I wrote the grandkids' names in the family Bible. [Just in case|So they know]"] = "В семейной Библии записаны имена внуков. [На всякий случай|Чтобы знали]",
    ["nobody came to relieve me. been here [16 hours|since 6 this morning]. still here"] = "никто не пришёл меня сменить. я здесь уже [16 часов|с 6 утра]. всё ещё здесь",
    ["told the kids we're camping. [they believed me|the little one didnt]"] = "Говорю детям, что мы в походе. [они мне поверили|младший не поверил]",
    ["the siren started again. [lost count today|i stopped counting]"] = "сирена опять заработала. [счёт потерян|уже не считаю]",
    ["going down to the [cellar|barn] to check the stores. be right back"] = "спускаюсь в [погреб|амбар] проверить запасы. сейчас вернусь",
    ["[made it to|im at] {jobPlace}. door's locked from the inside. ill wait here"] = "[на месте|я тут]: {jobPlace}. дверь заперта изнутри. подожду здесь",
    ["tell {mom} i love her. [i didnt say it enough|tell her im sorry about easter]"] = "{mom}: скажи ей, что я её люблю. [я слишком редко это говорил|скажи, что мне жаль за пасху]",
    ["the kids are at [my sisters|grandmas]. if anybody asks thats where they are. [dont come here|stay there]"] = "дети у [моей сестры|бабушки]. если кто спросит, они там. [не приходи сюда|оставайся там]",
    ["battery's [almost gone|on one bar]. [the radio says|they keep saying] stay inside. so im staying inside"] = "батарея [почти села|на одном делении]. [по радио говорят|всё твердят] сидеть дома. вот и сижу дома",
    ["[cant stop shaking|so cold]. its july and im under 2 blankets. probably nothing"] = "[никак не перестаёт трясти|ужасно холодно]. июль, а я под двумя одеялами. наверное, ерунда",
    ["if u see my car at the [IGA|lumberyard] dont stop. just keep going ok"] = "если увидишь мою машину у [IGA|лесопилки], не останавливайся. просто езжай дальше, ок",
    ["left the dog [with the neighbors|at the church]. [her name is Daisy|she likes the porch]"] = "собака [у соседей|в церкви]. [её зовут Дейзи|она любит крыльцо]",
    ["the spare key is [in the coffee can|under the gnome]. [take what you need|everything in the pantry is yours]"] = "запасной ключ [в банке из-под кофе|под садовым гномом]. [бери что нужно|всё в кладовой твоё]",
    ["somebody keeps trying the back door. [i turned the lights off|im in the bathroom]. text dont call"] = "кто-то всё пытается открыть заднюю дверь. [свет выключен|я в ванной]. пиши, не звони",
    ["I fed the cat and locked up. I'm going to sit on the porch a while. It's a pretty evening"] = "Кота покормили, дом заперт. Посижу ещё на крыльце. Красивый вечер",
    ["[still here|on shift]. we stopped counting. [dont wait up|kiss the kids for me]"] = "[всё ещё здесь|на смене]. мы перестали считать. [не жди|поцелуй за меня детей]",
    ["i wrapped it real tight. its fine. [just tired|gonna lie down a minute]"] = "перевязано туго. всё нормально. [просто усталость|прилягу на минутку]",
    ["[found|got] a ride with some guys from the plant. theyre going [south|to the river]. ill text when i can"] = "[нашлась|подвернулась] попутка с ребятами с завода. едут [на юг|к реке]. напишу, как смогу",
    ["[sorry about|forget about] the fight. it was stupid. [none of it matters|i was wrong]"] = "[прости за|забудь про] ссору. это было глупо. [всё это неважно|вина на мне]",
    ["{partner} if you get this, [the money's in the freezer|the papers are in the safe]. [I love you|Take care of them]"] = "{partner}, если ты получишь это, [деньги в морозилке|бумаги в сейфе]. [Люблю тебя|Береги их]",
    ["[taking|driving] the back way to the [pondview|IGA]. [car's|tank's] almost empty. wish me luck"] = "[еду|гоню] задворками в [pondview|IGA]. [машина почти на нуле|бак почти пуст]. пожелай мне удачи",
    ["{first} please. [Just one word|Just say ok]"] = "{first}, пожалуйста. [Одно слово|Просто скажи ок]",
    ["[came by|knocked] your place. door was open. [where did u go|call me]"] = "[Заходили к тебе|Стучали к тебе]. дверь была открыта. [где ты|позвони мне]",
    ["[I kept dinner warm|I left the porch light on]. I know. I'm leaving it on anyway"] = "[Ужин ещё тёплый|Свет на крыльце горит]. Знаю. Всё равно оставлю так",
    ["{first} you are listed missing. [Answer if you can|Radio in if you can]"] = "{first}, ты в списке пропавших без вести. [Ответь, если можешь|Выйди на связь по радио, если можешь]",
    ["The truck's fixed. Keys are on the hook. Come get it whenever. Love, Dad"] = "Грузовик починили. Ключи на крючке. Забирай когда захочешь. С любовью, папа",
    ["The church ladies asked about you. I said you're [busy|working]. Call me please"] = "Церковные дамы про тебя спрашивали. Говорю им, что ты [в делах|на работе]. Позвони мне, пожалуйста",
    ["moms freaking out. she made [3 pans of brownies|your bed twice]. just text back"] = "мама с ума сходит. она [испекла 3 противня брауни|дважды застелила твою кровать]. просто напиши",
    ["The kids keep asking. I told them you're at work. [Please come home|Don't make me a liar]"] = "Дети всё спрашивают. Говорю, что ты на работе. [Пожалуйста, вернись домой|Не заставляй меня врать]",
    ["[bobby|travis] came by looking for you. didnt say why. hit me up"] = "[бобби|трэвис] заходил, искал тебя. не сказал зачем. напиши",
    ["{first}, we need you [tomorrow|Saturday]. Half the crew's out. Text back if you're coming"] = "{first}, нужна твоя помощь [завтра|в субботу]. Половины бригады нет. Напиши, придёшь ли",
    ["Your [car payment|insurance bill] came. I put it by the phone. Let me know you got it"] = "Пришёл твой [платёж за машину|счёт за страховку]. Лежит у телефона. Напиши, как прочтёшь",
    ["Heard gunshots by [the river|the plant] last night. Don't go looking. Your mother's worried sick"] = "Прошлой ночью слышали выстрелы у [реки|завода]. Не ходи смотреть. Твоя мама места себе не находит",
    ["Power flickered [twice|three times]. Lanterns are out. Come home please"] = "Свет мигнул [дважды|трижды]. Фонари достали. Приезжай домой, пожалуйста",
    ["{first}, you're on the board for tonight. Confirm by radio. [Now|Please]"] = "{first}, ты сегодня в списке дежурных. Подтверди по радио. [Сейчас же|Пожалуйста]",
    ["Your name's on the prayer chain. I told them you're fine. Please call so I'm not lying to church people"] = "Твоё имя попало в молитвенную цепочку. Им сказано, что у тебя всё хорошо. Позвони, пожалуйста, чтобы мне не пришлось врать церковным людям",
    ["found your keys on the porch. screen door was open. [where are you|this isnt funny]"] = "ключи твои нашлись на крыльце. сетчатая дверь была открыта. [где ты|это не смешно]",
    ["The baby's fever broke. [I need you here|We need you]. I need you to see her"] = "У малышки спал жар. [Приезжай, без тебя тяжело|Приезжай, мы без тебя не справляемся]. Тебе надо её увидеть",
    ["Grandma fell [yesterday|Tuesday]. She keeps asking for you. [Just call her|Call her please]"] = "Бабушка упала [вчера|во вторник]. Она всё спрашивает о тебе. [Просто позвони ей|Позвони ей, пожалуйста]",
    ["the guard set up at the [school|fairgrounds]. they took our names and asked where u live. [i didnt know what to say|i said here]"] = "гвардия расположилась [в школе|на ярмарочной площади]. записали наши имена и спросили, где ты живёшь. [не знали, что сказать|сказали, что здесь]",
    ["I packed the car. We're going to {hometown}. [Come find us|I'll wait as long as I can]"] = "Машина загружена. Едем туда: {hometown}. [Найди нас|Буду ждать, сколько смогу]",
    ["The siren at the plant went off at 3am. Ran an hour. Your mother didn't sleep. Neither did I"] = "Сирена на заводе сработала в 3 ночи. Выла час. Твоя мама не спала. Я тоже",
    ["The dog won't stop staring at the back door. Deadbolt's thrown. Text me so I know you're ok"] = "Собака не отрывает глаз от задней двери. Засов задвинут. Напиши, дай знать, что ты в порядке",
    ["rev lois is writing down names of people who didnt come home. ur not on it. [dont be|call]"] = "преподобная лойс записывает имена тех, кто не вернулся домой. тебя там нет. [и не надо|позвони]",
    ["The [cherry|apple] pie is cooling. I saved you a slice. Just come home. Love, Mom"] = "[Вишнёвый|Яблочный] пирог остывает. Я оставила тебе кусок. Просто приезжай домой. С любовью, мама",
    ["I made [your favorite|the potato salad] in case you come. Your plate's in the fridge"] = "Я приготовила [твоё любимое|картофельный салат] на случай, если придёшь. Твоя тарелка в холодильнике",
    ["dude [ur mom|ur sister] keeps calling me. text her back. [seriously|please]"] = "чувак, [твоя мама|твоя сестра] мне всё звонит. напиши ей. [серьёзно|пожалуйста]",
    ["Drove by your place. [Car's there|Lights are off]. Knocked. I'll try again tomorrow"] = "Был у твоего дома. [Машина на месте|Свет не горит]. Постучал. Завтра попробую снова",
    ["[i'm not mad anymore|forget the money]. just answer"] = "[я уже не злюсь|забудь про деньги]. просто ответь",
    ["[I'm at the church|We're at the school] if you're looking for us. They have a list. Your name's on it"] = "[Я в церкви|Мы в школе], если ищешь нас. Там есть список. Твоё имя в нём",
    ["Someone said they saw you at the [gas station|IGA]. Was it you? Just say yes or no"] = "Кто-то сказал, что видел тебя [на заправке|в IGA]. Это был ты? Просто скажи да или нет",
    ["[your truck's|your bike's] still out front. i'm leaving it there. u'll want it"] = "[твой грузовик|твой велосипед] всё ещё стоит перед домом. оставляю там. тебе пригодится",
    ["{first} you missed [two|three] shifts. Not mad. Just let me know you're ok"] = "{first}, [две|три] смены без тебя. Не злюсь. Просто дай знать, что всё в порядке",
    ["Your mother wants you to know she's [praying|keeping a candle lit]. So am I. Call"] = "Твоя мама просит передать, что [молится|держит зажжённую свечу]. Я тоже. Позвони",
    ["i fed [ur fish|the cat]. its fine. i'll keep doing it. [come home|text me]"] = "я кормлю [твоих рыбок|кота]. всё нормально. буду продолжать. [возвращайся домой|напиши мне]",
    ["The baby said [dada|mama] today. I wanted you to know"] = "Малыш сегодня сказал [«дада»|«мама»]. Вот, сообщаю",
    ["[going to the river|heading to the school] tonight with everybody. [we'll wait for u|left a note on ur door]"] = "[идём к реке|идём в школу] сегодня вечером со всеми. [мы тебя подождём|записка на твоей двери]",
    ["Happy birthday sweetheart. I didn't forget. [I won't forget|I'll keep the cake]"] = "С днём рождения, солнышко. Помню. [Никогда не забуду|Оставлю торт]",
    ["Paycheck is in the office if you want it. [Door's unlocked|The manager has it]"] = "Зарплата в офисе, если хочешь забрать. [Дверь не заперта|Она у менеджера]",
    ["{first}, [call your mother|answer your mother]. She's [beside herself|not sleeping]"] = "{first}, [позвони маме|ответь маме]. Она [сама не своя|не спит]",
    ["The kids keep asking when you're coming home. [I don't know what to say|I said soon]"] = "Дети всё спрашивают, когда ты вернёшься домой. [Не знаю, что отвечать|Отвечаю: скоро]",
    ["{first}, [payroll|the office] needs your hours. [Call when you can|Is everything ok?]"] = "{first}, [расчётному отделу|офису] нужны твои часы. [Позвони, когда сможешь|Всё в порядке?]",
}
